#include "midi/JuceMidiBackend.h"
namespace jeff::daw {std::vector<DeviceIdentity>JuceMidiBackend::devices()const{std::vector<DeviceIdentity>v;for(auto&d:juce::MidiInput::getAvailableDevices())v.push_back({d.identifier.toStdString(),d.name.toStdString()});return v;}bool JuceMidiBackend::open(const std::string&id,Callback cb){close(id);auto i=juce::MidiInput::openDevice(id,this);if(!i)return false;callbacks[id]=std::move(cb);i->start();inputs[id]=std::move(i);return true;}void JuceMidiBackend::close(const std::string&id){inputs.erase(id);callbacks.erase(id);}void JuceMidiBackend::handleIncomingMidiMessage(juce::MidiInput*s,const juce::MidiMessage&m){if(!s)return;MidiMessage x;if(m.isNoteOn())x={MidiType::noteOn,(std::uint8_t)m.getChannel(),(std::uint8_t)m.getNoteNumber(),0,m.getFloatVelocity()};else if(m.isNoteOff())x={MidiType::noteOff,(std::uint8_t)m.getChannel(),(std::uint8_t)m.getNoteNumber()};else if(m.isChannelPressure())x={MidiType::pressure,(std::uint8_t)m.getChannel(),0,0,m.getChannelPressureValue()/127.f};else if(m.isPitchWheel())x={MidiType::pitch,(std::uint8_t)m.getChannel(),0,0,m.getPitchWheelValue()/16383.f};else if(m.isController())x={MidiType::cc,(std::uint8_t)m.getChannel(),(std::uint8_t)m.getControllerNumber(),(std::uint8_t)m.getControllerValue(),m.getControllerValue()/127.f};auto id=s->getIdentifier().toStdString();if(auto it=callbacks.find(id);it!=callbacks.end())it->second(id,x);}}
